CARDIO.register({"item":"p230","meta":{"num":"p230","label":"230","spe":"pneumo","short":"Douleur thoracique","title":"Douleur thoracique aiguë","section":"P","chapter":17,"pages":"267-279","sdd":[]},"objectives":[{"id":"p230-obj-01","rank":"A","rubric":"Définition","title":"Connaître la définition d'une douleur thoracique aiguë","desc":""},{"id":"p230-obj-02","rank":"A","rubric":"Diagnostic positif","title":"Savoir évoquer les 4 urgences cardio-vasculaires devant une douleur thoracique","desc":""},{"id":"p230-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","desc":""},{"id":"p230-obj-04","rank":"A","rubric":"Diagnostic positif","title":"Connaître la sémiologie clinique fonctionnelle et physique de la dissection aortique","desc":""},{"id":"p230-obj-05","rank":"B","rubric":"Étiologies","title":"Devant un angor d'effort, connaître les principales causes d'angor fonctionnel","desc":""},{"id":"p230-obj-06","rank":"A","rubric":"Étiologies","title":"Connaître les principales causes thoraciques de douleur aiguë en dehors des 4 urgences cardio-vasculaires","desc":""},{"id":"p230-obj-07","rank":"A","rubric":"Étiologies","title":"Connaître les principales causes extra-thoraciques de douleur thoracique","desc":""},{"id":"p230-obj-08","rank":"A","rubric":"Examens complémentaires","title":"Connaître les anomalies électrocardiographiques des 4 urgences cardio-vasculaires","desc":""},{"id":"p230-obj-09","rank":"A","rubric":"Examens complémentaires","title":"Connaître la place et les anomalies de la radiographie thoracique des 4 urgences cardio-vasculaires","desc":""},{"id":"p230-obj-10","rank":"A","rubric":"Examens complémentaires","title":"Connaître les examens biologiques à prescrire et leur interprétation des 4 urgences cardio-vasculaires","desc":""},{"id":"p230-obj-11","rank":"B","rubric":"Examens complémentaires","title":"Connaître la place de la coronarographie dans le diagnostic et les principes de prise en charge du syndrome coronarien aigu","desc":""},{"id":"p230-obj-12","rank":"B","rubric":"Examens complémentaires","title":"Connaître la place de l'échocardiographie, de l'ETO et du scanner thoracique dans le diagnostic de dissection aortique","desc":""},{"id":"p230-obj-13","rank":"A","rubric":"Identifier une urgence","title":"Savoir rechercher une détresse vitale devant une douleur thoracique","desc":""},{"id":"p230-obj-14","rank":"A","rubric":"Identifier une urgence","title":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p230-qroc-001","type":"QROC","rank":"A","objective":"p230-obj-01","tags":["définition","physiopathologie"],"difficulty":1,"question":"Quel élément du thorax, contrairement à la paroi, aux enveloppes (plèvre, péricarde), au cœur, à l'œsophage et à l'aorte, n'est pas une source de douleur ?","answer":"Le parenchyme pulmonaire","accept":["parenchyme pulmonaire","parenchyme","le parenchyme"],"keywords":["parenchyme"],"explanation":"La douleur thoracique naît de la paroi, des enveloppes (plèvre, péricarde) et de certains organes (cœur, œsophage, aorte), mais pas du parenchyme pulmonaire : une atteinte du poumon ne fait mal que si elle touche la plèvre.","src":"p. 268"},{"id":"p230-qroc-002","type":"QROC","rank":"A","objective":"p230-obj-02","tags":["urgence","définition"],"difficulty":1,"question":"Dans le moyen mnémotechnique « PIED » des urgences cardio-vasculaires (Péricardite, Infarctus, Embolie pulmonaire…), que désigne la lettre D ?","answer":"La dissection aortique","accept":["dissection aortique","dissection de l'aorte","dissection"],"keywords":["dissection"],"explanation":"PIED désigne les 4 urgences cardio-vasculaires à évoquer devant une douleur thoracique : Péricardite, Infarctus (SCA), Embolie pulmonaire, Dissection aortique.","src":"p. 271"},{"id":"p230-qroc-003","type":"QROC","rank":"A","objective":"p230-obj-02","tags":["urgence","définition"],"difficulty":1,"question":"Les cinq urgences à risque vital devant une douleur thoracique aiguë sont le SCA, l'EP, la tamponnade, la dissection aortique et … ?","answer":"Le pneumothorax compressif","accept":["pneumothorax compressif","pneumothorax","pno compressif","pno"],"keywords":["pneumothorax"],"explanation":"Le Collège retient cinq urgences associées à un risque vital : SCA, EP, tamponnade, dissection aortique et pneumothorax (PNO) compressif.","src":"p. 267"},{"id":"p230-qroc-004","type":"QROC","rank":"A","objective":"p230-obj-03","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Quels sont les trois examens indispensables devant toute douleur thoracique aiguë ?","answer":"ECG, mesure de la SpO2, radiographie thoracique","accept":["ecg, spo2, radiographie thoracique","ecg, saturation, radio du thorax","ecg, spo2, radio du thorax"],"keywords":["ecg","spo2","radio"],"explanation":"L'ECG, la mesure transcutanée de la SpO2 et la radiographie thoracique sont systématiques (avec la fréquence respiratoire). Les autres examens sont choisis selon les probabilités pré-test.","src":"p. 267, 269"},{"id":"p230-qroc-005","type":"QROC","rank":"A","objective":"p230-obj-03","tags":["diagnostic"],"difficulty":2,"question":"Pour l'EP et le SCA, quels seuils définissent une probabilité pré-test faible, intermédiaire et forte ?","answer":"Faible < 10 % ; intermédiaire 30-40 % ; forte > 60 %","accept":["< 10 %, 30-40 %, > 60 %","moins de 10, 30 a 40, plus de 60","10, 30-40, 60"],"keywords":["10","30","60"],"explanation":"Le contexte et la sémiologie donnent rarement un diagnostic de certitude, mais pour l'EP et le SCA ils permettent d'estimer une probabilité pré-test faible (< 10 %), intermédiaire (30-40 %) ou forte (> 60 %).","src":"p. 267"},{"id":"p230-qroc-006","type":"QROC","rank":"A","objective":"p230-obj-03","tags":["urgence"],"difficulty":1,"question":"Pourquoi le transport d'un patient suspect de SCA doit-il être médicalisé (appel du 15) ?","answer":"La mortalité pré-hospitalière est élevée","accept":["mortalite pre hospitaliere elevee","mortalite elevee","mortalite"],"keywords":["mortalité"],"explanation":"Le transport d'un patient suspect de SCA est médicalisé via le 15, car le risque de décès avant l'arrivée à l'hôpital est élevé.","src":"p. 271"},{"id":"p230-qroc-007","type":"QROC","rank":"A","objective":"p230-obj-03","tags":["urgence","traitement"],"difficulty":1,"question":"Quel objectif thérapeutique impose le diagnostic d'infarctus du myocarde aigu, dans les plus brefs délais ?","answer":"La désobstruction de l'artère coronaire occluse","accept":["desobstruction","reperfusion","revascularisation","angioplastie"],"keywords":["coronaire"],"explanation":"L'artère coronaire occluse doit être désobstruée le plus vite possible pour limiter l'étendue de la nécrose. Un aspect de SCA ST+ à l'ECG suffit pour lancer immédiatement la reperfusion.","src":"p. 267, 271"},{"id":"p230-qroc-008","type":"QROC","rank":"A","objective":"p230-obj-03","tags":["urgence","traitement"],"difficulty":1,"question":"Dès qu'une embolie pulmonaire est suspectée, quel traitement prescrit-on en attendant les résultats des examens ?","answer":"Une anticoagulation à dose curative","accept":["anticoagulation","anticoagulation curative","anticoagulation a posologie curative","anticoagulant a dose curative"],"keywords":["anticoag"],"explanation":"Dès la suspicion, on estime la probabilité clinique, on lance les examens adaptés, on prélève un bilan d'hémostase et on débute sans attendre une anticoagulation à posologie curative.","src":"p. 271"},{"id":"p230-qroc-009","type":"QROC","rank":"A","objective":"p230-obj-03","tags":["diagnostic","pièges"],"difficulty":1,"question":"Quel diagnostic reste suspecté jusqu'à preuve du contraire devant une dyspnée aiguë, avec ou sans douleur thoracique, sans anomalie auscultatoire franche et avec une radiographie thoracique « normale » ?","answer":"Une embolie pulmonaire","accept":["embolie pulmonaire","embolie"],"keywords":["embolie"],"explanation":"Dyspnée aiguë ± douleur thoracique avec auscultation sans anomalie franche et radiographie « normale » : EP suspectée jusqu'à preuve du contraire, a fortiori s'il existe une hypoxémie chez un sujet à facteurs de risque.","src":"p. 271"},{"id":"p230-qroc-010","type":"QROC","rank":"A","objective":"p230-obj-13","tags":["urgence","clinique"],"difficulty":2,"question":"Quels trois éléments font craindre la survenue d'un arrêt cardio-respiratoire chez un patient qui a une douleur thoracique ?","answer":"Bradypnée, bradycardie avec choc, troubles de la vigilance","accept":["bradypnee, bradycardie avec choc, troubles de la vigilance","bradypnee, bradycardie, troubles de la vigilance","bradypnee ou irregularites respiratoires, bradycardie, troubles de la vigilance"],"keywords":["bradypn","bradycard","vigilance"],"explanation":"Une respiration lente ou irrégulière, une bradycardie accompagnée de signes de choc et des troubles de la vigilance annoncent un arrêt cardio-respiratoire.","src":"p. 269"},{"id":"p230-qroc-011","type":"QROC","rank":"A","objective":"p230-obj-13","tags":["paraclinique","diagnostic"],"difficulty":1,"question":"En dessous de quelle valeur de SpO2 évoque-t-on une hypoxémie, à confirmer par les gaz du sang ?","answer":"SpO2 < 95 %","accept":["95","moins de 95","inferieure a 95"],"keywords":["95"],"explanation":"Une SpO2 < 95 % évoque une hypoxémie, à confirmer par la mesure des gaz du sang.","src":"p. 269"},{"id":"p230-qroc-012","type":"QROC","rank":"A","objective":"p230-obj-10","tags":["biologie","pièges"],"difficulty":1,"question":"Quelle précision doit toujours accompagner une gazométrie artérielle réalisée devant une douleur thoracique ?","answer":"Le débit d'oxygène du patient","accept":["debit d'oxygene","debit d'o2","debit oxygene"],"keywords":["débit","oxyg"],"explanation":"La gazométrie artérielle doit toujours préciser le débit d'oxygène reçu par le patient. Une bradypnée ou une tachypnée impose de plus de la réaliser d'emblée.","src":"p. 269, 270"},{"id":"p230-qroc-013","type":"QROC","rank":"A","objective":"p230-obj-10","tags":["biologie"],"difficulty":1,"question":"Si la première troponine ultrasensible est normale, à quel moment faut-il la répéter ?","answer":"À H3","accept":["h3","h 3","3h","3 h","3 heures","trois heures"],"keywords":["h3"],"explanation":"La troponine est dosée à l'arrivée puis répétée à H6 si elle est normale, à H3 si elle est ultrasensible. Un premier résultat normal n'élimine pas le SCA.","src":"p. 270"},{"id":"p230-qroc-014","type":"QROC","rank":"A","objective":"p230-obj-10","tags":["biologie","diagnostic"],"difficulty":2,"question":"Quelle variation de la troponine entre H0 et H3 permet d'affirmer le diagnostic de SCA ?","answer":"Un doublement","accept":["doublement","double","x2","x 2"],"keywords":["doubl"],"explanation":"Un doublement entre H0 et H3 permet d'affirmer le SCA ; une cinétique évolutive supérieure à 30 % est déjà très en faveur du diagnostic.","src":"p. 270"},{"id":"p230-qroc-015","type":"QROC","rank":"A","objective":"p230-obj-10","tags":["biologie","pièges"],"difficulty":2,"question":"En dehors du SCA, dans quelles trois situations la troponine peut-elle être positive ?","answer":"Péricardite, dissection aortique, embolie pulmonaire (retentissement droit)","accept":["pericardite, dissection aortique, embolie pulmonaire","pericardite, dissection, embolie pulmonaire"],"keywords":["péricardite","dissection","embolie"],"explanation":"La troponine témoigne d'une souffrance myocardique sans être spécifique du SCA : elle peut être positive dans la péricardite, la dissection aortique et l'embolie pulmonaire avec retentissement cardiaque droit.","src":"p. 270"},{"id":"p230-qroc-016","type":"QROC","rank":"A","objective":"p230-obj-10","tags":["biologie","diagnostic"],"difficulty":1,"question":"Pour quels niveaux de probabilité clinique d'embolie pulmonaire dose-t-on les D-dimères ?","answer":"Faible ou modérée","accept":["faible ou moderee","faible ou intermediaire","faible a moderee","faible et moderee","faible moderee","faible intermediaire"],"keywords":["faible","modér"],"explanation":"Les D-dimères se dosent si la probabilité clinique d'EP est faible ou modérée ; le choix et la hiérarchie des autres examens dépendent de la probabilité pré-test (item 226).","src":"p. 270"},{"id":"p230-qroc-017","type":"QROC","rank":"A","objective":"p230-obj-08","tags":["ECG","diagnostic"],"difficulty":1,"question":"À l'ECG, quels deux éléments associés au sus-décalage ST évoquent un SCA ST+ ?","answer":"L'onde de Pardee et le signe du miroir","accept":["onde de pardee et signe du miroir","pardee et miroir","pardee miroir"],"keywords":["pardee","miroir"],"explanation":"Sus-décalage ST, onde de Pardee et signe du miroir évoquent un SCA ST+ : prise en charge immédiate, avec éventuelle revascularisation coronaire. Un ECG inter-critique normal n'élimine pas le diagnostic.","src":"p. 270"},{"id":"p230-qroc-018","type":"QROC","rank":"A","objective":"p230-obj-08","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quel aspect du sus-décalage ST, sans signe du miroir, évoque une péricardite à l'ECG ?","answer":"Un sus-décalage ST concave","accept":["concave","st concave","sus decalage concave"],"keywords":["concave"],"explanation":"Péricardite : sus-décalage ST concave sans signe du miroir ; un épanchement péricardique de grande abondance ajoute un microvoltage diffus.","src":"p. 270"},{"id":"p230-qroc-019","type":"QROC","rank":"A","objective":"p230-obj-08","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quels signes ECG sont des signes indirects de cœur pulmonaire aigu, par exemple au cours d'une embolie pulmonaire ?","answer":"Onde P ample, S1Q3, déviation axiale droite","accept":["onde p ample, s1q3, deviation axiale droite","p ample, s1q3, axe droit","p ample s1q3 axe droit"],"keywords":["p ample","s1","droit"],"explanation":"Une onde P ample, un aspect S1Q3 et une déviation axiale droite sont des signes indirects de cœur pulmonaire aigu, par exemple dans l'EP.","src":"p. 270"},{"id":"p230-qroc-020","type":"QROC","rank":"A","objective":"p230-obj-08","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quel aspect des complexes QRS, associé à une tachycardie et à un microvoltage, évoque une tamponnade ?","answer":"L'alternance électrique","accept":["alternance electrique","alternance electrique des qrs","alternance"],"keywords":["alternance"],"explanation":"L'alternance électrique (amplitude des QRS variable dans une même dérivation), la tachycardie et le microvoltage évoquent une tamponnade, gazeuse en cas de pneumothorax compressif, péricardique en cas d'épanchement péricardique.","src":"p. 270, 273"},{"id":"p230-qroc-021","type":"QROC","rank":"A","objective":"p230-obj-04","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quels sont le type et l'irradiation de la douleur d'une dissection aortique ?","answer":"Déchirement, irradiant dans le dos (vers les lombes)","accept":["dechirement dans le dos","dechirement irradiant dans le dos","dechirure dorsale"],"keywords":["déchir","dos"],"explanation":"La douleur est aiguë, prolongée, intense, en déchirement, irradiant dans le dos et migrant vers les lombes.","src":"p. 271"},{"id":"p230-qroc-022","type":"QROC","rank":"A","objective":"p230-obj-04","tags":["clinique"],"difficulty":1,"question":"Quelle asymétrie tensionnelle entre les deux bras évoque une dissection aortique ?","answer":"Plus de 20 mmHg","accept":["20","20 mmhg","plus de 20","superieure a 20"],"keywords":["20"],"explanation":"Une asymétrie tensionnelle supérieure à 20 mmHg entre les deux bras est évocatrice ; un souffle d'insuffisance aortique ou un déficit neurologique peuvent s'y associer.","src":"p. 271"},{"id":"p230-qroc-023","type":"QROC","rank":"A","objective":"p230-obj-04","tags":["étiologie","clinique"],"difficulty":1,"question":"Chez un sujet jeune, quel type de maladie faut-il évoquer devant une dissection aortique ?","answer":"Une maladie héréditaire du tissu conjonctif (Marfan, Ehlers-Danlos)","accept":["marfan","ehlers danlos","maladie du tissu conjonctif","tissu conjonctif"],"keywords":["conjonctif"],"explanation":"Après 60 ans, la dissection survient surtout sur une aorte athéroscléreuse due à une HTA non contrôlée ; chez le sujet plus jeune, on évoque une maladie héréditaire du tissu conjonctif (syndrome de Marfan, d'Ehlers-Danlos).","src":"p. 271"},{"id":"p230-qroc-024","type":"QROC","rank":"A","objective":"p230-obj-09","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Quel signe radiographique thoracique évoque une dissection aortique ?","answer":"Un élargissement du médiastin","accept":["elargissement du mediastin","mediastin elargi","elargissement mediastinal","double contour aortique"],"keywords":["médiastin"],"explanation":"La radiographie peut montrer un élargissement du médiastin, parfois un double contour aortique ou un épanchement pleural (hémothorax par rupture de l'aorte thoracique).","src":"p. 270, 272"},{"id":"p230-qroc-025","type":"QROC","rank":"A","objective":"p230-obj-09","tags":["imagerie"],"difficulty":1,"question":"Quel aspect de la silhouette cardiaque peut-on voir à la radiographie dans une tamponnade ?","answer":"Une cardiomégalie en « carafe »","accept":["carafe","en carafe","coeur en carafe","cardiomegalie en carafe"],"keywords":["carafe"],"explanation":"La radiographie montre une cardiomégalie d'aspect en carafe, mais elle peut être normale : c'est l'échographie cardiaque qui confirme le diagnostic.","src":"p. 273"},{"id":"p230-qroc-026","type":"QROC","rank":"B","objective":"p230-obj-12","tags":["imagerie","diagnostic"],"difficulty":2,"question":"Quelle forme d'échocardiographie est surtout utile pour confirmer une dissection aortique ?","answer":"L'échocardiographie transœsophagienne (ETO)","accept":["eto","transoesophagienne","echocardiographie transoesophagienne","echo transoesophagienne"],"keywords":["œsophag"],"explanation":"L'échocardiographie confirme la dissection, par voie transthoracique et surtout transœsophagienne.","src":"p. 272"},{"id":"p230-qroc-027","type":"QROC","rank":"B","objective":"p230-obj-12","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Chez un patient stable, quel examen d'imagerie vasculaire confirme une dissection aortique, en plus de l'échocardiographie ?","answer":"L'angioscanner (ou l'angio-IRM) thoracique aortique","accept":["angioscanner","angio-irm","angio irm","scanner","irm"],"keywords":["scanner"],"explanation":"Si le patient est stable, l'angioscanner ou l'angio-IRM thoracique aortique confirme la dissection ; l'angioscanner montre un double contraste dans la lumière aortique avec un « flap ».","src":"p. 272, 273"},{"id":"p230-qroc-028","type":"QROC","rank":"B","objective":"p230-obj-11","tags":["traitement","urgence"],"difficulty":1,"question":"Dans le SCA ST+, avant quel délai après le début des douleurs l'efficacité de la coronarographie est-elle maximale ?","answer":"Moins de 2 heures","accept":["2 heures","2 h","2h","moins de 2 heures","deux heures"],"keywords":["2"],"explanation":"La coronarographie est à réaliser en urgence dans le SCA ST+ ; c'est la technique de reperfusion de choix si elle est faite le plus tôt possible, avec une efficacité maximale avant 2 heures de douleur.","src":"p. 270"},{"id":"p230-qroc-029","type":"QROC","rank":"B","objective":"p230-obj-11","tags":["traitement","urgence"],"difficulty":2,"question":"Si le délai prévisible de la coronarographie dépasse 2 heures dans un SCA ST+, quelle revascularisation est préconisée ?","answer":"Une fibrinolyse intraveineuse suivie d'une angioplastie","accept":["fibrinolyse","fibrinolyse intraveineuse","fibrinolyse iv","thrombolyse"],"keywords":["fibrinolyse"],"explanation":"Quand la coronarographie ne peut pas être faite dans les 2 heures, la reperfusion repose sur une fibrinolyse intraveineuse, suivie d'une angioplastie.","src":"p. 270"},{"id":"p230-qroc-030","type":"QROC","rank":"B","objective":"p230-obj-11","tags":["traitement"],"difficulty":2,"question":"Dans un SCA non ST+, dans quel délai la coronarographie doit-elle être réalisée ?","answer":"Dans les 24 heures","accept":["24 h","24h","24 heures","dans les 24 h","moins de 24 h"],"keywords":["24"],"explanation":"En cas de SCA non ST+, on réalise la coronarographie dans les 24 heures, alors que le SCA ST+ est une urgence immédiate.","src":"p. 270"},{"id":"p230-qroc-031","type":"QROC","rank":"B","objective":"p230-obj-05","tags":["étiologie"],"difficulty":2,"question":"Devant un angor typique sans lésion coronaire expliquant les symptômes, quelle valvulopathie serrée peut être responsable d'un angor fonctionnel ?","answer":"Le rétrécissement aortique","accept":["retrecissement aortique","stenose aortique","rao"],"keywords":["rétrécissement"],"explanation":"Les causes d'angor fonctionnel citées sont le rétrécissement aortique serré, la cardiomyopathie hypertrophique, les tachycardies (fibrillation atriale), l'anémie et l'hyperthyroïdie.","src":"p. 271"},{"id":"p230-qroc-032","type":"QROC","rank":"A","objective":"p230-obj-03","tags":["clinique","diagnostic"],"difficulty":1,"question":"Comment appelle-t-on la baisse de la pression artérielle systolique de plus de 10 mmHg à l'inspiration observée dans la tamponnade ?","answer":"Le pouls paradoxal (de Küssmaul)","accept":["pouls paradoxal","paradoxal","kussmaul","pouls de kussmaul"],"keywords":["paradox"],"explanation":"Le pouls paradoxal est une baisse de la PAS de plus de 10 mmHg à l'inspiration par rapport à l'expiration. La tamponnade associe une hypotension et des signes d'insuffisance cardiaque droite, sans signe d'insuffisance cardiaque gauche.","src":"p. 273"},{"id":"p230-qroc-033","type":"QROC","rank":"A","objective":"p230-obj-03","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Quel examen confirme le diagnostic de tamponnade ?","answer":"L'échographie cardiaque","accept":["echographie cardiaque","echocardiographie","echo cardiaque","echo"],"keywords":["écho"],"explanation":"La tamponnade est suspectée sur la clinique et l'ECG, puis confirmée par l'échographie cardiaque ; la radiographie thoracique peut être normale.","src":"p. 273"},{"id":"p230-qroc-034","type":"QROC","rank":"A","objective":"p230-obj-06","tags":["définition"],"difficulty":1,"question":"Comment définit-on un pneumothorax ?","answer":"Présence d'air dans l'espace pleural","accept":["air dans l'espace pleural","air dans la plevre","air dans la cavite pleurale","presence d'air dans la plevre"],"keywords":["air","pleur"],"explanation":"Le pneumothorax est la présence d'air dans l'espace pleural, avec collapsus partiel ou complet du poumon. Un antécédent de PNO est un argument fort : il récidive dans près d'un tiers des cas.","src":"p. 273"},{"id":"p230-qroc-035","type":"QROC","rank":"A","objective":"p230-obj-06","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quels sont les deux signes cliniques qui font évoquer un pneumothorax à l'examen ?","answer":"Asymétrie auscultatoire et tympanisme","accept":["asymetrie auscultatoire et tympanisme","tympanisme et asymetrie auscultatoire","asymetrie auscultatoire, tympanisme"],"keywords":["asymétrie","tympanisme"],"explanation":"Le diagnostic de pneumothorax est en général aisé : asymétrie auscultatoire et tympanisme à l'examen, confirmés par le cliché de thorax.","src":"p. 273"},{"id":"p230-qroc-036","type":"QROC","rank":"A","objective":"p230-obj-14","tags":["urgence","pièges"],"difficulty":2,"question":"Quels sont les deux signes de gravité d'un pneumothorax (la douleur thoracique n'en fait pas partie) ?","answer":"Détresse respiratoire et chute tensionnelle","accept":["detresse respiratoire et chute tensionnelle","detresse respiratoire et hypotension","detresse respiratoire, chute tensionnelle"],"keywords":["détresse","tension"],"explanation":"Dans le pneumothorax, la gravité tient à la détresse respiratoire et à la chute tensionnelle ; la douleur thoracique n'est pas un signe de gravité.","src":"p. 273"},{"id":"p230-qroc-037","type":"QROC","rank":"A","objective":"p230-obj-06","tags":["diagnostic","clinique"],"difficulty":1,"question":"En l'absence d'urgence vitale, quel élément de l'analyse de la douleur guide l'algorithme diagnostique ?","answer":"L'influence de la respiration sur la douleur","accept":["influence de la respiration","effet de la respiration","respiration","rythmee par la respiration"],"keywords":["respiration"],"explanation":"On distingue les douleurs rythmées par la respiration (pleurales et pariétales, trachéobronchites, EP) des douleurs qui ne le sont pas (SCA, péricardites, douleurs œsophagiennes, autres).","src":"p. 267, 275"},{"id":"p230-qroc-038","type":"QROC","rank":"A","objective":"p230-obj-06","tags":["clinique","diagnostic"],"difficulty":1,"question":"Au bout de combien de temps la douleur d'un angor d'effort stable cède-t-elle après l'arrêt de l'effort ou la prise de trinitrine ?","answer":"Environ 2 à 5 minutes","accept":["2 a 5 min","2 a 5 minutes","2-5 min","2 a 5","entre 2 et 5 minutes"],"keywords":["2","5"],"explanation":"La douleur de l'angor d'effort stable, déclenchée par l'effort, est calmée 2 à 5 minutes après l'arrêt de l'effort ou la prise de trinitrine ; l'ECG est normal en dehors des crises.","src":"p. 277"},{"id":"p230-qroc-039","type":"QROC","rank":"A","objective":"p230-obj-06","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quelle position soulage la douleur d'une péricardite aiguë ?","answer":"La position penchée en avant","accept":["penche en avant","penchee en avant","position penchee en avant","anteflexion"],"keywords":["penché","avant"],"explanation":"La douleur de péricardite (précordiale gauche ou rétrosternale, parfois augmentée par l'inspiration profonde) est soulagée par la position penchée en avant, contrairement aux douleurs pariétales ou pulmonaires. La position allongée la déclenche.","src":"p. 268, 277"},{"id":"p230-qroc-040","type":"QROC","rank":"A","objective":"p230-obj-06","tags":["étiologie"],"difficulty":2,"question":"Devant une péricardite chronique, quelles deux étiologies faut-il suspecter ?","answer":"Une tuberculose ou une néoplasie","accept":["tuberculose ou neoplasie","tuberculose et neoplasie","tuberculose ou cancer","tuberculose et cancer","tuberculose neoplasie"],"keywords":["tubercul","néoplasi"],"explanation":"La péricardite aiguë ou subaiguë est souvent virale ; devant une péricardite chronique, il faut suspecter une tuberculose ou une néoplasie.","src":"p. 277"},{"id":"p230-qroc-041","type":"QROC","rank":"A","objective":"p230-obj-06","tags":["étiologie","urgence"],"difficulty":2,"question":"Quels sont les trois diagnostics que la prise de cocaïne peut faire évoquer devant une douleur thoracique ?","answer":"SCA (voire coronarospasme), myopéricardite, pneumothorax","accept":["sca, myopericardite, pneumothorax","infarctus, myopericardite, pneumothorax","sca myopericardite pneumothorax"],"keywords":["sca","myopéricardite","pneumothorax"],"explanation":"La cocaïne peut provoquer un SCA (voire un coronarospasme de Prinzmetal), une myopéricardite ou un pneumothorax lié aux efforts inspiratoires (sniff) ; sa consommation doit être recherchée systématiquement à l'interrogatoire.","src":"p. 278"},{"id":"p230-qroc-042","type":"QROC","rank":"A","objective":"p230-obj-07","tags":["étiologie","clinique"],"difficulty":1,"question":"Quel syndrome associe des efforts de vomissements, une douleur et une hématémèse, par dilacération de la muqueuse du bas œsophage ?","answer":"Le syndrome de Mallory-Weiss","accept":["mallory-weiss","mallory weiss","mallory"],"keywords":["mallory"],"explanation":"Dans le syndrome de Mallory-Weiss, la muqueuse du bas œsophage et du cardia se dilacère après des efforts de vomissements, avec douleur puis hématémèse ; la rupture œsophagienne (syndrome de Boerhaave) est à part.","src":"p. 278"},{"id":"p230-qroc-043","type":"QROC","rank":"A","objective":"p230-obj-07","tags":["diagnostic","pièges"],"difficulty":1,"question":"Quel diagnostic doit être éliminé avant de retenir une origine œsophagienne à une douleur thoracique ?","answer":"Un syndrome coronarien aigu (SCA)","accept":["sca","syndrome coronarien aigu","infarctus","infarctus du myocarde"],"keywords":["sca"],"explanation":"L'œsophage et le cœur ont une innervation commune : une douleur œsophagienne (RGO, spasmes) peut simuler un SCA, et on ne retient l'origine œsophagienne qu'après avoir exclu un SCA.","src":"p. 278"},{"id":"p230-qroc-044","type":"QROC","rank":"A","objective":"p230-obj-07","tags":["traitement","pièges"],"difficulty":2,"question":"Quels médicaments peuvent faire céder des spasmes œsophagiens ?","answer":"Les dérivés nitrés et le phloroglucinol","accept":["derives nitres et phloroglucinol","nitres et phloroglucinol","trinitrine et phloroglucinol","nitres, phloroglucinol"],"keywords":["nitr","phloroglucinol"],"explanation":"Les spasmes œsophagiens, qui peuvent simuler un SCA, peuvent céder aux dérivés nitrés et au phloroglucinol. Attention : les dérivés nitrés peuvent donc aussi soulager une douleur œsophagienne.","src":"p. 278"},{"id":"p230-qroc-045","type":"QROC","rank":"A","objective":"p230-obj-07","tags":["diagnostic","pièges"],"difficulty":1,"question":"Quel statut a toujours le diagnostic de douleur thoracique psychogène, souvent difficile à poser ?","answer":"Un diagnostic d'élimination","accept":["diagnostic d'elimination","elimination","d'elimination"],"keywords":["éliminat"],"explanation":"La douleur psychogène (parfois crise d'angoisse ou attaque de panique) a une description variable, sans lien avec l'effort, un cortège de signes associés riche et des examens normaux : c'est toujours un diagnostic d'élimination.","src":"p. 278"},{"id":"p230-qru-101","type":"QRU","rank":"A","objective":"p230-obj-03","tags":["urgence","ECG"],"difficulty":1,"stem":"Un homme de 58 ans, fumeur, appelle le 15 pour une douleur thoracique rétrosternale constrictive, irradiant à la mâchoire, survenue au repos depuis 30 minutes. L'ECG montre un sus-décalage ST avec onde de Pardee et signe du miroir. Quelle attitude est la plus adaptée ?","options":[{"t":"Reperfusion immédiate, transport médicalisé via le 15","ok":true,"why":"Un aspect de SCA ST+ à l'ECG suffit pour mettre en œuvre immédiatement la reperfusion ; le transport doit être médicalisé car la mortalité pré-hospitalière est élevée."},{"t":"Attendre la troponine de contrôle à H3 avant de décider","ok":false,"why":"Le SCA ST+ se reconnaît à l'ECG : la décision ne doit pas attendre la biologie."},{"t":"Réaliser d'abord un angioscanner thoracique","ok":false,"why":"L'angioscanner sert à confirmer une dissection aortique chez un patient stable ; il ne doit pas retarder la reperfusion d'un SCA ST+."},{"t":"Doser les D-dimères avant toute prise en charge","ok":false,"why":"Les D-dimères se dosent si la probabilité clinique d'EP est faible ou modérée, ce qui n'est pas le contexte ici."},{"t":"Faire venir le patient à l'hôpital par ses propres moyens","ok":false,"why":"Le transport d'un patient suspect de SCA doit être médicalisé (15)."}],"explanation":"Sus-décalage ST avec onde de Pardee et signe du miroir = SCA ST+ : prise en charge immédiate incluant une éventuelle revascularisation coronaire (coronarographie en urgence, ou fibrinolyse puis angioplastie si le délai prévisible dépasse 2 h), sans attendre la troponine.","src":"p. 270, 271"},{"id":"p230-qru-102","type":"QRU","rank":"A","objective":"p230-obj-04","tags":["diagnostic","clinique"],"difficulty":1,"stem":"Un homme de 67 ans, hypertendu mal contrôlé, consulte pour une douleur thoracique brutale, intense, en déchirement, irradiant dans le dos puis vers les lombes. La pression artérielle diffère de plus de 20 mmHg entre les deux bras. Quel diagnostic évoquez-vous en priorité ?","options":[{"t":"Dissection aortique","ok":true,"why":"Douleur en déchirement migratrice vers les lombes et asymétrie tensionnelle > 20 mmHg, sur un terrain d'HTA non contrôlée après 60 ans."},{"t":"Péricardite aiguë","ok":false,"why":"Sa douleur est soulagée par la position penchée en avant ; elle n'explique pas l'asymétrie tensionnelle entre les bras."},{"t":"Pneumothorax","ok":false,"why":"Il se reconnaît à l'asymétrie auscultatoire et au tympanisme."},{"t":"Spasme œsophagien","ok":false,"why":"Cause digestive fréquente pouvant simuler un SCA, retenue seulement après exclusion d'un SCA."},{"t":"Angor d'effort stable","ok":false,"why":"Douleur déclenchée par l'effort et calmée en 2 à 5 minutes, ce qui ne correspond pas à une douleur brutale en déchirement."}],"explanation":"Douleur aiguë, intense, en déchirement, migratrice vers les lombes, avec asymétrie tensionnelle > 20 mmHg : dissection aortique, favorisée après 60 ans par une aorte athéroscléreuse (HTA non contrôlée).","src":"p. 271"},{"id":"p230-qru-103","type":"QRU","rank":"A","objective":"p230-obj-03","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Une femme de 29 ans consulte pour une dyspnée aiguë avec une douleur thoracique latérale. L'auscultation est sans anomalie franche, la radiographie thoracique est « normale » et la SpO2 est à 92 %. Quel diagnostic faut-il suspecter jusqu'à preuve du contraire ?","options":[{"t":"Une embolie pulmonaire","ok":true,"why":"Dyspnée aiguë ± douleur thoracique, auscultation et radiographie sans anomalie franche, hypoxémie : EP suspectée jusqu'à preuve du contraire."},{"t":"Un pneumothorax","ok":false,"why":"Son diagnostic est en général aisé (asymétrie auscultatoire, tympanisme, signes sur le cliché de thorax), ce qui n'est pas le cas ici."},{"t":"Une pneumonie","ok":false,"why":"Elle est confirmée par la radiographie thoracique, ici normale."},{"t":"Une trachéobronchite aiguë","ok":false,"why":"Diagnostic clinique : brûlure à chaque mouvement respiratoire, toux sèche, cortège viral. Ce tableau est différent."},{"t":"Une douleur psychogène","ok":false,"why":"C'est un diagnostic d'élimination : toutes les investigations doivent être normales, ce qui n'est pas le cas avec une SpO2 à 92 %."}],"explanation":"Toute dyspnée aiguë ± douleur thoracique, sans anomalie auscultatoire franche et avec une radiographie thoracique « normale », est suspecte d'EP jusqu'à preuve du contraire, a fortiori en cas d'hypoxémie (SpO2 < 95 %).","trap":"Une radiographie « normale » n'écarte pas l'embolie pulmonaire.","src":"p. 269, 271"},{"id":"p230-qru-104","type":"QRU","rank":"A","objective":"p230-obj-10","tags":["biologie","diagnostic"],"difficulty":1,"stem":"Chez quel patient les D-dimères sont-ils indiqués dans le bilan d'une douleur thoracique aiguë ?","options":[{"t":"Celui dont la probabilité d'EP est faible ou modérée","ok":true,"why":"C'est l'indication citée : D-dimères si la probabilité clinique d'embolie pulmonaire est faible ou modérée."},{"t":"Celui qui a un sus-décalage ST avec onde de Pardee","ok":false,"why":"Le diagnostic de SCA ST+ repose sur l'ECG ; la reperfusion ne doit pas attendre."},{"t":"Celui qui présente un tympanisme et une asymétrie auscultatoire","ok":false,"why":"Ces signes orientent vers un pneumothorax, confirmé par le cliché de thorax."},{"t":"Celui qui décrit une brûlure à chaque mouvement respiratoire","ok":false,"why":"C'est le tableau clinique d'une trachéobronchite aiguë, dont le diagnostic est clinique."},{"t":"Celui dont la douleur cède en 2 à 5 minutes à l'arrêt de l'effort","ok":false,"why":"C'est la description d'un angor d'effort stable."}],"explanation":"Les D-dimères se dosent quand la probabilité clinique d'EP est faible ou modérée ; le choix et la hiérarchie des examens dépendent des probabilités pré-test (item 226).","src":"p. 269, 270"},{"id":"p230-qru-105","type":"QRU","rank":"A","objective":"p230-obj-08","tags":["ECG","diagnostic"],"difficulty":1,"stem":"Un homme de 32 ans, après un épisode viral, présente une douleur précordiale gauche majorée en position allongée et soulagée penché en avant. Quel aspect de l'ECG est le plus attendu ?","options":[{"t":"Sus-décalage ST concave sans signe du miroir","ok":true,"why":"C'est l'aspect de la péricardite aiguë."},{"t":"Sus-décalage ST avec onde de Pardee et signe du miroir","ok":false,"why":"Cet aspect évoque un SCA ST+."},{"t":"Onde P ample, S1Q3 et déviation axiale droite","ok":false,"why":"Signes indirects de cœur pulmonaire aigu, par exemple dans l'EP."},{"t":"Alternance électrique des QRS avec tachycardie et microvoltage","ok":false,"why":"Cet aspect évoque une tamponnade, complication redoutable mais rare de la péricardite."},{"t":"Un ECG toujours normal","ok":false,"why":"L'ECG participe au diagnostic de péricardite par le sus-décalage ST concave sans signe du miroir."}],"explanation":"Péricardite aiguë (contexte viral fréquent, douleur soulagée penché en avant) : sus-décalage ST concave sans signe du miroir ; un épanchement péricardique abondant ajoute un microvoltage diffus.","src":"p. 270, 277"},{"id":"p230-qru-106","type":"QRU","rank":"A","objective":"p230-obj-06","tags":["diagnostic","clinique"],"difficulty":1,"stem":"Un homme de 55 ans, hypertendu et fumeur, décrit une douleur thoracique constrictive survenant à la marche rapide et cédant en 3 à 4 minutes à l'arrêt de l'effort. L'ECG réalisé en dehors des crises est normal. Quel diagnostic est le plus probable ?","options":[{"t":"Angor d'effort stable","ok":true,"why":"Douleur déclenchée par l'effort, calmée 2 à 5 minutes après l'arrêt de l'effort ou la prise de trinitrine, ECG normal en dehors des crises."},{"t":"Péricardite aiguë","ok":false,"why":"La douleur est soulagée par la position penchée en avant et n'est pas déclenchée par l'effort."},{"t":"Trachéobronchite aiguë","ok":false,"why":"Douleur en brûlure à chaque mouvement respiratoire, avec toux sèche et cortège viral."},{"t":"Zona thoracique","ok":false,"why":"Douleur métamérique précédée d'hyperesthésie et de brûlures, suivie d'une éruption vésiculeuse."},{"t":"Douleur psychogène","ok":false,"why":"Description variable, sans lien avec l'effort, et diagnostic d'élimination."}],"explanation":"Une douleur d'effort, calmée en quelques minutes (2 à 5 min) par l'arrêt de l'effort ou la trinitrine, avec un ECG normal entre les crises, évoque un angor d'effort stable.","src":"p. 276-278"},{"id":"p230-qru-107","type":"QRU","rank":"A","objective":"p230-obj-14","tags":["urgence","pièges"],"difficulty":2,"stem":"Chez un patient présentant un pneumothorax, quel élément constitue un signe de gravité ?","options":[{"t":"Une chute tensionnelle","ok":true,"why":"La détresse respiratoire et la chute tensionnelle sont les signes de gravité du pneumothorax."},{"t":"Une douleur thoracique intense","ok":false,"why":"La douleur thoracique n'est pas un signe de gravité du pneumothorax."},{"t":"Un tympanisme à la percussion","ok":false,"why":"C'est un signe clinique du diagnostic, non un signe de gravité."},{"t":"Un antécédent de pneumothorax","ok":false,"why":"C'est un argument fort pour le diagnostic (récidive dans près d'un tiers des cas), non un signe de gravité."},{"t":"Une asymétrie auscultatoire","ok":false,"why":"C'est un signe clinique du diagnostic, non un signe de gravité."}],"explanation":"Dans le pneumothorax, ce sont la détresse respiratoire et la chute tensionnelle qui signent la gravité ; la douleur thoracique n'est pas un signe de gravité.","trap":"Ne pas juger la gravité d'un pneumothorax à l'intensité de la douleur.","src":"p. 273"},{"id":"p230-qcm-101","type":"QRM","rank":"A","objective":"p230-obj-01","tags":["définition","physiopathologie"],"difficulty":1,"stem":"Parmi les propositions suivantes sur ce qui fait mal dans le thorax, laquelle ou lesquelles sont exactes ?","options":[{"t":"Le parenchyme pulmonaire n'est pas, en lui-même, source de douleur","ok":true,"why":"Seules les pathologies pulmonaires survenant au contact de la plèvre sont éventuellement douloureuses."},{"t":"Le parenchyme pulmonaire est la source la plus fréquente de douleur thoracique","ok":false,"why":"Il n'est pas sensible : la douleur vient de la paroi, des enveloppes et de certains organes."},{"t":"Une pneumonie est toujours douloureuse","ok":false,"why":"La douleur n'existe que s'il y a un contact pleural."},{"t":"La plèvre et le péricarde ne peuvent pas être douloureux","ok":false,"why":"Ces enveloppes font partie de ce qui fait mal dans le thorax."},{"t":"L'œsophage ne peut pas être à l'origine d'une douleur thoracique","ok":false,"why":"Cœur, œsophage et aorte sont des organes pouvant être douloureux."}],"explanation":"Ce qui fait mal dans le thorax : la paroi (côtes, muscles), les enveloppes (plèvre, péricarde) et certains organes (cœur, œsophage, aorte), mais pas le parenchyme pulmonaire.","src":"p. 268, 275"},{"id":"p230-qcm-102","type":"QRM","rank":"A","objective":"p230-obj-14","tags":["urgence","clinique"],"difficulty":2,"stem":"Parmi les signes suivants, lesquels sont des signes de gravité respiratoires à rechercher devant une douleur thoracique ?","options":[{"t":"Cyanose","ok":true,"why":"Signe de gravité respiratoire."},{"t":"Tirage","ok":true,"why":"Signe de lutte respiratoire."},{"t":"Balancement thoraco-abdominal","ok":true,"why":"L'asynchronisme thoraco-abdominal est un autre signe de lutte respiratoire."},{"t":"Marbrures","ok":false,"why":"Signe de choc, donc de gravité cardiovasculaire."},{"t":"Lipothymie ou syncope","ok":false,"why":"Signes de gravité neurologiques."}],"explanation":"Gravité respiratoire : cyanose, tachypnée, signes de lutte (tirage, balancement thoraco-abdominal). Gravité cardiovasculaire : pâleur, tachycardie, hypotension, signes de choc. Gravité neurologique : lipothymie ou syncope, agitation ou troubles de la vigilance.","src":"p. 269"},{"id":"p230-qcm-103","type":"QRM","rank":"A","objective":"p230-obj-13","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Que faut-il rechercher à l'interrogatoire d'un patient qui consulte pour une douleur thoracique aiguë ?","options":[{"t":"Les antécédents coronariens personnels et familiaux","ok":true,"why":"Ils font partie des antécédents à rechercher."},{"t":"Les antécédents de maladie thrombo-embolique veineuse","ok":true,"why":"Ils font partie des antécédents à rechercher."},{"t":"La consommation de cocaïne, surtout chez un sujet jeune sans antécédent","ok":true,"why":"Complication fréquente de cette toxicomanie, qui doit systématiquement être recherchée."},{"t":"La prise d'une pilule œstro-progestative","ok":true,"why":"Traitement en cours à rechercher en particulier."},{"t":"Les traitements en cours n'ont aucun intérêt","ok":false,"why":"L'interrogatoire recherche les traitements en cours, en particulier la pilule œstro-progestative."}],"explanation":"L'interrogatoire recherche les antécédents personnels et familiaux (coronariens, maladie thrombo-embolique veineuse, maladies respiratoires, cancer), les facteurs de risque cardiovasculaire dont le tabagisme, la cocaïne et les traitements en cours.","src":"p. 269"},{"id":"p230-qcm-104","type":"QRM","rank":"A","objective":"p230-obj-08","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Quelles associations entre un aspect de l'ECG et son diagnostic sont exactes ?","options":[{"t":"Sus-décalage ST avec onde de Pardee et signe du miroir : SCA ST+","ok":true,"why":"Aspect typique de SCA ST+, qui impose une prise en charge immédiate."},{"t":"Onde P ample, S1Q3, déviation axiale droite : cœur pulmonaire aigu","ok":true,"why":"Signes indirects de cœur pulmonaire aigu, par exemple dans l'EP."},{"t":"Sus-décalage ST concave sans signe du miroir : SCA ST+","ok":false,"why":"Un sus-décalage concave sans signe du miroir évoque une péricardite."},{"t":"Alternance électrique des QRS avec tachycardie et microvoltage : tamponnade","ok":true,"why":"Aspect évocateur de tamponnade, gazeuse ou péricardique."},{"t":"Dissection aortique : ECG toujours très anormal","ok":false,"why":"Dans la dissection, l'ECG est le plus souvent normal."}],"explanation":"Pardee + miroir = SCA ST+ ; ST concave sans miroir = péricardite ; P ample, S1Q3, axe droit = cœur pulmonaire aigu ; alternance électrique + microvoltage + tachycardie = tamponnade ; dissection : ECG le plus souvent normal.","src":"p. 270"},{"id":"p230-qcm-105","type":"QRM","rank":"A","objective":"p230-obj-10","tags":["biologie","diagnostic"],"difficulty":2,"stem":"À propos de la troponine devant une suspicion de SCA, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Un premier dosage normal n'exclut pas le SCA","ok":true,"why":"La normalité initiale ne doit pas exclure le diagnostic : le dosage est répété."},{"t":"Une troponine positive est spécifique du SCA","ok":false,"why":"Elle peut être positive dans la péricardite, la dissection aortique et l'EP avec retentissement cardiaque droit."},{"t":"Elle n'est jamais répétée si le premier dosage est normal","ok":false,"why":"Elle est répétée à H6, ou à H3 si la troponine est ultrasensible."},{"t":"Une cinétique évolutive > 30 % est sans intérêt","ok":false,"why":"Une cinétique évolutive supérieure à 30 % est très en faveur du SCA."},{"t":"Son résultat doit être attendu avant de rechercher une urgence","ok":false,"why":"L'attente des examens biologiques ne doit pas retarder la recherche d'une situation d'urgence."}],"explanation":"Troponine : dosage à l'arrivée, répété si normale ; cinétique > 30 % très en faveur du SCA ; doublement entre H0 et H3 = diagnostic ; elle peut aussi être positive dans la péricardite, la dissection aortique et l'EP avec retentissement droit.","src":"p. 270"},{"id":"p230-qcm-106","type":"QRM","rank":"B","objective":"p230-obj-11","tags":["traitement","urgence"],"difficulty":2,"stem":"Concernant la reperfusion dans le SCA ST+, quelles propositions sont exactes ?","options":[{"t":"La coronarographie est un geste à réaliser en urgence","ok":true,"why":"C'est la technique de reperfusion de choix si le délai de réalisation est le plus court possible."},{"t":"Son efficacité est maximale avant 2 heures de douleur","ok":true,"why":"L'efficacité est maximale si elle est faite moins de 2 heures après le début des douleurs."},{"t":"Si le délai prévisible dépasse 2 heures, on préconise une fibrinolyse intraveineuse suivie d'une angioplastie","ok":true,"why":"C'est l'attitude préconisée en cas de délai prévisible supérieur à 2 heures."},{"t":"Il faut attendre la troponine avant de reperfuser","ok":false,"why":"Un aspect de SCA ST+ à l'ECG suffit pour mettre en œuvre immédiatement les thérapeutiques de reperfusion."},{"t":"Dans un SCA non ST+, la coronarographie se fait dans les 48 heures","ok":false,"why":"Elle se réalise dans les 24 heures."}],"explanation":"SCA ST+ : coronarographie en urgence (efficacité maximale avant 2 h) ; si le délai prévisible dépasse 2 h, fibrinolyse intraveineuse puis angioplastie. SCA non ST+ : coronarographie dans les 24 h.","src":"p. 270, 271"},{"id":"p230-qcm-107","type":"QRM","rank":"B","objective":"p230-obj-11","tags":["traitement","urgence"],"difficulty":3,"stem":"Concernant un SCA évoluant depuis plus de 12 heures, quelles propositions sont exactes ?","options":[{"t":"L'angioplastie primaire reste indiquée en cas de douleurs persistantes","ok":true,"why":"Les douleurs persistantes maintiennent l'indication de l'angioplastie primaire."},{"t":"L'angioplastie primaire reste indiquée en cas d'instabilité hémodynamique ou rythmique","ok":true,"why":"Instabilité hémodynamique ou troubles du rythme ventriculaires : l'indication est maintenue."},{"t":"Une angioplastie est à considérer jusqu'à 48 heures après le début des symptômes","ok":true,"why":"C'est le délai jusqu'auquel une angioplastie est à considérer."},{"t":"Au-delà de 48 heures sans douleur, on fait d'emblée l'angioplastie sans autre examen","ok":false,"why":"On recherche d'abord une viabilité dans le territoire infarci."},{"t":"Une angioplastie n'est jamais indiquée après 12 heures","ok":false,"why":"Elle reste indiquée dans les situations de douleurs persistantes ou d'instabilité."}],"explanation":"Après 12 h : angioplastie primaire encore indiquée si douleurs persistantes ou instabilité hémodynamique/rythmique ; à considérer jusqu'à 48 h ; au-delà, sans douleur, on recherche d'abord une viabilité dans le territoire infarci.","src":"p. 270"},{"id":"p230-qcm-108","type":"QRM","rank":"A","objective":"p230-obj-04","tags":["clinique","diagnostic"],"difficulty":1,"stem":"À propos de la dissection aortique, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Asymétrie tensionnelle > 20 mmHg entre les deux bras","ok":true,"why":"Signe de la sémiologie physique de la dissection aortique."},{"t":"Elle survient surtout avant 30 ans","ok":false,"why":"Elle est plus fréquente à partir de 60 ans."},{"t":"La douleur est calmée par la position penchée en avant","ok":false,"why":"C'est la douleur de péricardite ; la dissection donne une douleur en déchirement irradiant dans le dos."},{"t":"L'ECG est toujours anormal","ok":false,"why":"L'ECG est le plus souvent normal ; il est anormal si une artère coronaire est lésée."},{"t":"C'est une cause très fréquente de douleur thoracique","ok":false,"why":"C'est une pathologie exceptionnelle."}],"explanation":"Pathologie exceptionnelle, plus fréquente à partir de 60 ans : douleur aiguë en déchirement irradiant dans le dos, asymétrie tensionnelle > 20 mmHg, souffle d'insuffisance aortique ou déficit neurologique possibles ; ECG le plus souvent normal.","src":"p. 271"},{"id":"p230-qcm-109","type":"QRM","rank":"B","objective":"p230-obj-12","tags":["imagerie","diagnostic"],"difficulty":2,"stem":"Quels éléments participent au diagnostic de dissection aortique ?","options":[{"t":"Un élargissement du médiastin à la radiographie thoracique","ok":true,"why":"La radiographie peut montrer un élargissement du médiastin, parfois un double contour aortique."},{"t":"Une échocardiographie, surtout transœsophagienne","ok":true,"why":"L'échocardiographie confirme le diagnostic, transthoracique et surtout transœsophagienne."},{"t":"Un angioscanner ou une angio-IRM aortique si le patient est stable","ok":true,"why":"Ils confirment le diagnostic chez un patient stable."},{"t":"Un ECG normal, qui permet d'écarter le diagnostic","ok":false,"why":"L'ECG est le plus souvent normal : il n'élimine pas la dissection."},{"t":"Une radiographie thoracique seule, qui suffit à confirmer","ok":false,"why":"Le diagnostic est confirmé par l'échocardiographie et l'angioscanner ou l'angio-IRM."}],"explanation":"Radiographie : élargissement du médiastin, parfois double contour aortique ou épanchement pleural. Confirmation : échocardiographie (surtout transœsophagienne) et, si le patient est stable, angioscanner ou angio-IRM thoracique aortique.","src":"p. 270, 272"},{"id":"p230-qcm-110","type":"QRM","rank":"A","objective":"p230-obj-03","tags":["clinique","diagnostic"],"difficulty":1,"stem":"À propos de la tamponnade, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Elle comprime les cavités cardiaques droites","ok":true,"why":"C'est une compression aiguë des cavités cardiaques droites par un épanchement péricardique d'installation habituellement rapide et abondant."},{"t":"Elle complique fréquemment la péricardite","ok":false,"why":"Complication redoutable mais rare (2 % des péricardites)."},{"t":"Elle comprime les cavités cardiaques gauches","ok":false,"why":"Ce sont les cavités cardiaques droites qui sont comprimées."},{"t":"Elle s'accompagne de signes d'insuffisance cardiaque gauche","ok":false,"why":"On observe des signes d'insuffisance cardiaque droite, sans signe d'insuffisance cardiaque gauche."},{"t":"Elle est confirmée par la radiographie thoracique","ok":false,"why":"La radiographie peut être normale ; c'est l'échographie cardiaque qui confirme."}],"explanation":"Tamponnade (2 % des péricardites) : compression aiguë des cavités cardiaques droites par un épanchement péricardique rapide et abondant, notamment néoplasique ; hypotension, signes d'insuffisance cardiaque droite sans signe d'insuffisance cardiaque gauche ; l'échographie cardiaque confirme.","src":"p. 273"},{"id":"p230-qcm-111","type":"QRM","rank":"A","objective":"p230-obj-06","tags":["clinique","imagerie"],"difficulty":2,"stem":"Concernant le pneumothorax, quelles propositions sont exactes ?","options":[{"t":"Il correspond à la présence d'air dans l'espace pleural","ok":true,"why":"Avec collapsus partiel ou complet du poumon."},{"t":"Un antécédent de pneumothorax est un argument fort pour le diagnostic","ok":true,"why":"Il récidive dans près d'un tiers des cas."},{"t":"L'asymétrie auscultatoire et le tympanisme orientent le diagnostic","ok":true,"why":"Le diagnostic est en général aisé cliniquement, puis sur le cliché de thorax."},{"t":"L'intensité de la douleur est son principal signe de gravité","ok":false,"why":"La douleur thoracique n'est pas un signe de gravité : ce sont la détresse respiratoire et la chute tensionnelle."},{"t":"Il se traduit à la radiographie par une hyperdensité sans vaisseaux","ok":false,"why":"Il donne une hyperclarté sans structures vasculaires, avec poumon rétracté sur le hile."}],"explanation":"Pneumothorax : air dans l'espace pleural ; antécédent = argument fort ; asymétrie auscultatoire et tympanisme ; hyperclarté sans vaisseaux à la radiographie ; gravité = détresse respiratoire et chute tensionnelle, pas la douleur.","src":"p. 273, 274"},{"id":"p230-qcm-112","type":"QRM","rank":"A","objective":"p230-obj-06","tags":["diagnostic","imagerie"],"difficulty":2,"stem":"À propos du pneumomédiastin, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Le scanner thoracique permet d'en faire le diagnostic","ok":true,"why":"Le scanner est l'examen qui permet le diagnostic."},{"t":"Il est toujours associé à un pneumothorax","ok":false,"why":"Il est seulement parfois associé à un pneumothorax."},{"t":"C'est une cause fréquente de douleur thoracique","ok":false,"why":"Le pneumomédiastin est rare."},{"t":"Il est uniquement d'origine traumatique","ok":false,"why":"Il peut être traumatique ou spontané."},{"t":"Il donne une douleur épigastrique d'installation progressive","ok":false,"why":"La douleur est rétrosternale, d'installation brusque, avec emphysème sous-cutané cervical."}],"explanation":"Pneumomédiastin rare, parfois associé à un pneumothorax, traumatique ou spontané : douleur rétrosternale brusque, emphysème sous-cutané cervical avec crépitation, hyperclarté en double contour sur la radiographie ; le scanner fait le diagnostic.","src":"p. 274, 275"},{"id":"p230-qcm-113","type":"QRM","rank":"A","objective":"p230-obj-06","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Quelle(s) douleur(s) est/sont rythmée(s) par la respiration ?","options":[{"t":"La douleur d'un épanchement pleural","ok":true,"why":"Elle est majorée par l'inspiration et la toux."},{"t":"La douleur de l'angor d'effort stable","ok":false,"why":"Elle est déclenchée par l'effort : douleur non influencée par la respiration."},{"t":"La douleur d'un syndrome coronarien aigu","ok":false,"why":"Le SCA fait partie des douleurs non rythmées par la respiration."},{"t":"La douleur œsophagienne","ok":false,"why":"Elle fait partie des douleurs non rythmées par la respiration."},{"t":"La douleur d'un zona thoracique","ok":false,"why":"Elle est classée parmi les douleurs non influencées par la respiration."}],"explanation":"Douleurs rythmées par la respiration : pleurales et pariétales, trachéobronchites, EP. Douleurs non rythmées : SCA, péricardites, douleurs œsophagiennes, angor d'effort stable, zona.","src":"p. 267, 276, 277"},{"id":"p230-qcm-114","type":"QRM","rank":"A","objective":"p230-obj-06","tags":["clinique","étiologie"],"difficulty":1,"stem":"À propos de la péricardite aiguë, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Elle est le plus souvent idiopathique ou virale","ok":true,"why":"Le contexte viral est fréquent dans la douleur thoracique aiguë ou subaiguë."},{"t":"La douleur est calmée par la position allongée","ok":false,"why":"La position allongée déclenche la douleur ; la position penchée en avant la soulage."},{"t":"La douleur est aggravée par la position penchée en avant","ok":false,"why":"Elle est soulagée par la position penchée en avant."},{"t":"La tamponnade en est une complication fréquente","ok":false,"why":"Complication redoutable mais rare (2 % des péricardites)."},{"t":"La radiographie thoracique est toujours très anormale","ok":false,"why":"La radiographie est le plus souvent normale dans la péricardite."}],"explanation":"Péricardite aiguë : idiopathique ou virale le plus souvent, douleur précordiale gauche ou rétrosternale soulagée penché en avant (déclenchée allongé), radiographie le plus souvent normale ; complication rare : tamponnade.","src":"p. 268, 270, 273, 277"},{"id":"p230-qcm-115","type":"QRM","rank":"A","objective":"p230-obj-07","tags":["étiologie","pièges"],"difficulty":2,"stem":"Une cause digestive est envisagée devant une douleur thoracique : laquelle ou lesquelles de ces propositions sont exactes ?","options":[{"t":"On exclut un SCA avant d'incriminer l'œsophage","ok":true,"why":"L'œsophage et le cœur ont une innervation commune : l'origine œsophagienne ne se retient qu'après exclusion d'un SCA."},{"t":"Un RGO ne peut pas simuler un SCA","ok":false,"why":"Il peut simuler un SCA (douleur constrictive avec irradiation)."},{"t":"Les spasmes œsophagiens ne cèdent jamais aux dérivés nitrés","ok":false,"why":"Ils peuvent céder aux dérivés nitrés et au phloroglucinol."},{"t":"Le syndrome de Mallory-Weiss est une rupture de l'œsophage","ok":false,"why":"C'est une dilacération de la muqueuse du bas œsophage et du cardia ; la rupture œsophagienne est le syndrome de Boerhaave."},{"t":"Les causes digestives se limitent aux lésions de l'œsophage","ok":false,"why":"Il existe aussi des causes gastro-duodénales, pancréatiques ou hépatiques (pancréatite aiguë, perforation d'ulcère, cholécystite aiguë)."}],"explanation":"RGO et spasmes œsophagiens sont des causes fréquentes qui peuvent simuler un SCA : on n'en retient l'origine qu'après avoir exclu un SCA. Mallory-Weiss : dilacération muqueuse après vomissements ; Boerhaave : rupture œsophagienne, rarissime.","src":"p. 278"},{"id":"p230-qcm-116","type":"QRM","rank":"A","objective":"p230-obj-07","tags":["diagnostic","épidémiologie"],"difficulty":1,"stem":"Concernant les douleurs thoraciques psychogènes, quelles propositions sont exactes ?","options":[{"t":"Elles représentent jusqu'à un quart des douleurs thoraciques vues aux urgences","ok":true,"why":"C'est la fréquence rapportée aux urgences."},{"t":"Elles s'intègrent parfois dans une crise d'angoisse aiguë ou une attaque de panique","ok":true,"why":"Avec un cortège de signes associés riche et varié (palpitations, tremblements, sudations, frissons, nausées)."},{"t":"C'est toujours un diagnostic d'élimination","ok":true,"why":"Toutes les investigations sont normales et le diagnostic est souvent difficile."},{"t":"La douleur est typiquement déclenchée par l'effort","ok":false,"why":"La description est variable en intensité, sans lien avec l'effort."},{"t":"Les examens complémentaires sont habituellement anormaux","ok":false,"why":"L'ensemble des investigations est normal."}],"explanation":"Douleur psychogène : jusqu'à un quart des douleurs thoraciques aux urgences, description variable sans lien avec l'effort, cortège riche de signes associés, examens normaux : toujours un diagnostic d'élimination.","src":"p. 278"},{"id":"p230-qcm-117","type":"QRM","rank":"B","objective":"p230-obj-05","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"Devant un angor typique sans atteinte coronarienne expliquant les symptômes, quelles causes d'angor fonctionnel peut-on évoquer ?","options":[{"t":"Un rétrécissement aortique serré","ok":true,"why":"Cause d'angor fonctionnel citée."},{"t":"Une cardiomyopathie hypertrophique","ok":true,"why":"Cause d'angor fonctionnel citée."},{"t":"Une tachycardie, par exemple une fibrillation atriale","ok":true,"why":"Les tachycardies sont citées comme cause d'angor fonctionnel."},{"t":"Une anémie","ok":true,"why":"Cause d'angor fonctionnel citée."},{"t":"Une hypothyroïdie","ok":false,"why":"C'est l'hyperthyroïdie qui est citée parmi les causes d'angor fonctionnel."}],"explanation":"Causes d'angor fonctionnel : rétrécissement aortique serré, cardiomyopathie hypertrophique, tachycardies (fibrillation atriale), anémie, hyperthyroïdie.","src":"p. 271"},{"id":"p230-qcm-118","type":"QRM","rank":"A","objective":"p230-obj-03","tags":["diagnostic","urgence"],"difficulty":2,"stem":"Concernant l'embolie pulmonaire devant une douleur thoracique aiguë, quelles propositions sont exactes ?","options":[{"t":"Les signes de thrombose veineuse sont absents dans un tiers des cas","ok":true,"why":"Les signes cliniques ont une faible valeur prédictive, ce qui rend le diagnostic difficile."},{"t":"Une anticoagulation à dose curative est débutée dès la suspicion","ok":true,"why":"On la prescrit en attendant les résultats des investigations."},{"t":"Les D-dimères se dosent si la probabilité clinique est faible ou modérée","ok":true,"why":"C'est l'indication des D-dimères citée dans le bilan."},{"t":"Une radiographie thoracique normale permet de l'éliminer","ok":false,"why":"Une dyspnée aiguë avec radiographie « normale » est suspecte d'EP jusqu'à preuve du contraire."},{"t":"La douleur thoracique est indispensable au diagnostic","ok":false,"why":"Il s'agit d'une dyspnée aiguë avec ou sans douleur thoracique."}],"explanation":"EP : diagnostic difficile (faible valeur prédictive des signes cliniques, thrombose veineuse absente dans 1/3 des cas) ; on évalue la probabilité clinique, on prélève un bilan d'hémostase et on anticoagule à dose curative sans attendre.","src":"p. 270, 271"},{"id":"p230-qcm-119","type":"QRM","rank":"A","objective":"p230-obj-03","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Concernant la sémiologie de la douleur thoracique, quelles propositions sont exactes ?","options":[{"t":"Une douleur constrictive, en étau, évoque une origine coronaire","ok":true,"why":"La douleur constrictive en étau ou de pesanteur évoque une origine coronaire."},{"t":"Une irradiation vers le cou, la mâchoire et les bras évoque une douleur coronarienne","ok":true,"why":"Ce sont les irradiations des douleurs coronariennes."},{"t":"Une irradiation vers le dos évoque une douleur aortique ou pancréatique","ok":true,"why":"Irradiation vers le dos : douleur aortique et pancréatique."},{"t":"Une douleur majorée par l'inspiration profonde et la toux est typiquement coronaire","ok":false,"why":"Elle est essentiellement d'origine pariétale thoracique (paroi, plèvre) ou pulmonaire avec contact pariétal."},{"t":"Une irradiation intercostale évoque une douleur aortique","ok":false,"why":"L'irradiation intercostale évoque une névralgie ou un zona."}],"explanation":"Constrictive/en étau, irradiant au cou, à la mâchoire et aux bras : coronaire ; irradiant vers le dos : aortique ou pancréatique ; intercostale : névralgie, zona ; rythmée par la respiration ou majorée à la palpation : pariétale.","src":"p. 268"},{"id":"p230-qru-108","type":"QRU","rank":"A","objective":"p230-obj-02","tags":["urgence","définition"],"difficulty":1,"stem":"Parmi les urgences vitales suivantes devant une douleur thoracique aiguë, laquelle ne fait PAS partie du moyen mnémotechnique « PIED » des urgences cardio-vasculaires ?","options":[{"t":"Pneumothorax","ok":true,"why":"Le pneumothorax compressif complète les urgences cardio-vasculaires dans la liste des cinq urgences à risque vital, mais ne fait pas partie de PIED."},{"t":"Péricardite aiguë","ok":false,"why":"C'est le P de PIED."},{"t":"Infarctus du myocarde (SCA)","ok":false,"why":"C'est le I de PIED."},{"t":"Embolie pulmonaire","ok":false,"why":"C'est le E de PIED."},{"t":"Dissection aortique","ok":false,"why":"C'est le D de PIED."}],"explanation":"PIED = Péricardite, Infarctus (SCA), Embolie pulmonaire, Dissection aortique ; le pneumothorax compressif s'ajoute à la tamponnade, au SCA, à l'EP et à la dissection dans la liste des cinq urgences à risque vital.","src":"p. 267, 271"},{"id":"p230-qcm-120","type":"QRM","rank":"A","objective":"p230-obj-09","tags":["imagerie","diagnostic"],"difficulty":2,"stem":"Concernant la radiographie thoracique devant une douleur thoracique aiguë, quelles propositions sont exactes ?","options":[{"t":"Elle est systématique, avec l'ECG et la mesure de la SpO2","ok":true,"why":"Ce sont les trois examens indispensables."},{"t":"Un élargissement du médiastin évoque une dissection aortique","ok":true,"why":"Elle peut aussi montrer un double contour aortique ou un épanchement pleural."},{"t":"Elle est le plus souvent normale dans la péricardite","ok":true,"why":"Le diagnostic de péricardite repose surtout sur la clinique et l'ECG."},{"t":"Une radiographie normale permet d'éliminer une embolie pulmonaire","ok":false,"why":"Une dyspnée aiguë avec radiographie « normale » est suspecte d'EP jusqu'à preuve du contraire."},{"t":"Une radiographie normale élimine une tamponnade","ok":false,"why":"L'aspect en carafe n'est pas constant : la radiographie peut être normale, et c'est l'échographie cardiaque qui confirme."}],"explanation":"Radiographie de face en inspiration : pathologie pleurale ou parenchymateuse, élargissement du médiastin (dissection), cardiomégalie (insuffisance cardiaque gauche, tamponnade), le plus souvent normale dans la péricardite ; si le cliché ne tranche pas, le scanner est indiqué en deuxième intention.","src":"p. 267, 270, 273"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p230-pareto","points":[{"id":"p230-par-01","rank":"A","cat":"gravité","text":"4 urgences cardio-vasculaires : **PIED** = Péricardite, Infarctus (SCA), Embolie pulmonaire, Dissection aortique ; 5 urgences vitales = SCA, EP, **tamponnade**, dissection, **PNO compressif**","src":"p. 267, 271"},{"id":"p230-par-02","rank":"A","cat":"examen","text":"D'emblée : **ECG + SpO2 + radio thorax** ; gaz du sang si brady/tachypnée (préciser le **débit d'O2**) ; SpO2 < **95 %** = hypoxémie","src":"p. 267, 269"},{"id":"p230-par-03","rank":"A","cat":"examen","text":"ECG : **ST sus-décalé + onde de Pardee + signe du miroir** = SCA ST+ → reperfusion **immédiate** sans attendre la troponine ; ECG inter-critique normal n'élimine pas","src":"p. 270, 271"},{"id":"p230-par-04","rank":"B","cat":"traitement","text":"SCA ST+ : **coronarographie** en urgence (max < **2 h**) ; délai > 2 h → **fibrinolyse** IV puis angioplastie ; non ST+ → coro < **24 h** ; transport médicalisé (**15**)","src":"p. 270, 271"},{"id":"p230-par-05","rank":"A","cat":"examen","text":"**Troponine** : arrivée puis **H3** (ultrasensible) ou H6 ; > **30 %** = très en faveur ; **doublement** H0-H3 = SCA ; normale n'exclut pas ; + aussi péricardite, dissection, EP","src":"p. 270"},{"id":"p230-par-06","rank":"A","cat":"clinique","text":"**Dissection aortique** : douleur en **déchirement** dorsale migrant aux lombes ; asymétrie tensionnelle > **20 mmHg** ; ± souffle d'IA ; > 60 ans (HTA) ; jeune : Marfan, Ehlers-Danlos","src":"p. 271"},{"id":"p230-par-07","rank":"A","cat":"examen","text":"Dissection : **Rx** = élargissement du médiastin ; **ECG** souvent normal ; confirmation **ETO** puis **angioscanner** ou angio-IRM si stable","src":"p. 270, 272"},{"id":"p230-par-08","rank":"A","cat":"piège","text":"**EP** : dyspnée aiguë ± douleur, auscultation + radio **normales** = EP jusqu'à preuve du contraire ; **anticoagulation curative** dès la suspicion ; TVP absente dans **1/3** des cas","src":"p. 271"},{"id":"p230-par-09","rank":"A","cat":"clinique","text":"**Tamponnade** (cavités droites) : hypotension + signes d'IC **droite** sans IC gauche ; **pouls paradoxal** (PAS ↓ > 10 mmHg à l'inspiration) ; Rx cœur en carafe ; **écho** confirme","src":"p. 273"},{"id":"p230-par-10","rank":"A","cat":"gravité","text":"**PNO** : air pleural ; **asymétrie auscultatoire + tympanisme** ; gravité = **détresse respiratoire + chute tensionnelle**, PAS la douleur ; ATCD = argument fort","src":"p. 273"},{"id":"p230-par-11","rank":"A","cat":"examen","text":"ECG : ST **concave** sans miroir = péricardite ; **P ample + S1Q3 + axe droit** = cœur pulmonaire aigu ; **alternance électrique** + microvoltage + tachycardie = tamponnade","src":"p. 270"},{"id":"p230-par-12","rank":"A","cat":"gravité","text":"Gravité : resp. (**cyanose**, tachypnée, tirage) ; CV (hypotension, **choc**) ; neuro (**syncope**, agitation) ; bradypnée + bradycardie + vigilance ↓ = risque d'**ACR**","src":"p. 269"},{"id":"p230-par-13","rank":"A","cat":"clinique","text":"Sans urgence vitale, la **respiration** guide : rythmée (pleurale, pariétale, trachéobronchite, EP) vs non rythmée (**SCA**, péricardite, œsophage) ; pariétal = reproductible à la palpation","src":"p. 267, 276"},{"id":"p230-par-14","rank":"A","cat":"clinique","text":"**Péricardite** : soulagée **penché en avant**, aggravée allongé ; contexte viral ; si chronique → **tuberculose** ou néoplasie ; complication = tamponnade","src":"p. 268, 277"},{"id":"p230-par-15","rank":"A","cat":"étiologie","text":"Hors urgence : SCA, **RGO/œsophage** et **psychogène** (jusqu'à 1/4 des DT aux urgences) ; psychogène = diagnostic d'**élimination** ; exclure un **SCA** avant d'accuser l'œsophage","src":"p. 267, 278"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
